# Generated by `shiny theme new` from shiny-trail
# Base scheme: Kanagawa Dragon — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely (see THEMES.md); `shiny theme check` lints it, `shiny theme set <name>` re-applies.
THEME_BASE="Kanagawa Dragon"
GHOSTTY_THEME="Kanagawa Dragon"   # built-in: ghostty +list-themes
ACCENT_PRESET=1   # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#181616"          # window background
BG_DARK="#0D0C0C"     # frames, omnibox
SURFACE="#282727"     # borders, dividers, inactive window border
SELECTION="#453C2E"   # selected rows, text selection
MUTED="#393836"       # shortcuts, scrollbar
COMMENT="#737C73"     # subtext, inactive tabs
FG="#C5C9C5"          # primary text
FG_DIM="#A6A69C"      # secondary text
ACCENT="#E6C384"      # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#B6927B"     # secondary accent: cursor, shortcuts, search selection
